'use strict';
(function(){
function renderSong(){const label=$('#garageSong');if(!label)return;const session=state.music.session,song=session&&M.song(state,session.songId),present=session&&state.people.some(p=>session.participants.includes(p.id)&&p.room==='garage'&&!p.travel&&p.action==='practice');label.hidden=!song||!present||!!state.tour?.active;if(label.hidden){label.innerHTML='';return;}label.innerHTML=`<small>${session.kind==='trial'?'Essai':'Répétition'}</small><strong class="song-heading">${I.songTitle(song)}</strong>`;}
function renderGarage(){renderSong();const el=$('#garageInstruments');if(!el)return;el.innerHTML=(['departing','stage','result','returning'].includes(state.tour.active?.phase)?[]:H.garageLayout(state)).map(station=>{const p=state.people.find(p=>p.id===station.id),playing=p.room==='garage'&&!p.travel&&['practice','jam'].includes(p.action),portable=!['Batterie','Clavier','Percussions'].includes(p.instrument);return `<g transform="translate(${station.x} ${station.y}) rotate(${station.angle})" class="garage-station ${playing?'playing':''}"><ellipse cx="0" cy="30" rx="${portable?28:45}" ry="12" fill="#35463a" opacity=".13"/>${!playing||!portable?`<image href="${I.instrumentAsset(p.instrument)}" x="${portable?-31:-47}" y="${portable?-40:-24}" width="${portable?62:94}" height="${portable?62:94}"/>`:''}</g>`;}).join('');}
window.MaisonGarageUI={render:renderGarage};
})();
